import ghidra.app.script.GhidraScript;import java.nio.file.*;import java.util.*;public class MatrixEntries extends GhidraScript {public void run() throws Exception {TreeSet<String> entries=new TreeSet<>();StringBuilder refs=new StringBuilder();for(var line:Files.readAllLines(Path.of(getScriptArgs()[0]))){var a=toAddr(line);var f=getFunctionContaining(a);refs.append(a+"\t"+(f==null?"none":f.getEntryPoint())+"\n");if(f!=null)entries.add(f.getEntryPoint().toString());}Files.writeString(Path.of(getScriptArgs()[1]),String.join("\n",entries));Files.writeString(Path.of(getScriptArgs()[2]),refs.toString());}}